examples.code:
P1 = {0,0,0}: P2 = {3,0,0}: P3 = {0,4,0}
V1 = {P2(0)-P1(0), P2(1)-P1(1), P2(2)-P1(2)}
V2 = {P3(0)-P1(0), P3(1)-P1(1), P3(2)-P1(2)}
Normale = VECTOR.CROSS(V1, V2)
N = VECTOR.NORMALIZE(Normale)
PRINT "Normale al triangolo:"
PRINT "x: "; FORMAT(N(0),"#.00")
PRINT "y: "; FORMAT(N(1),"#.00")
PRINT "z: "; FORMAT(N(2),"#.00")
